const oldInitial=initialState;
function prepare(s){s.preferences ||= {};const defaults={wallpaper:'bloom',theme:'Light',accent:'#0067c0',taskbarAlignment:'Center',displayScale:'100',volume:70,brightness:85,bluetooth:false,wifi:true,notifications:true,nightLight:false,textSize:100,timezone:'America/New_York',time24:false,language:'English (United States)',location:false,gameMode:true};for(const[k,v]of Object.entries(defaults))if(s.preferences[k]===undefined)s.preferences[k]=v;s.office ||= {word:{name:'Document1',html:'<h1>IT Support Lab Notes</h1><p>Record your observations, diagnosis, and resolution here.</p>'},excel:{name:'Workbook1',cells:{A1:'Ticket',B1:'Minutes',A2:'LAB-001',B2:'15',A3:'LAB-002',B3:'20',A4:'Total',B4:'=SUM(B2:B3)'}},powerpoint:{name:'Presentation1',slides:[{title:'IT Support Home Lab',body:'Identity • Connectivity • Endpoint security\nA hands-on training portfolio',theme:'blue'}],active:0}};s.notepad ||= {tabs:[{path:'C:\\Lab\\notes.txt',text:s.files['C:\\Lab\\notes.txt']||'',dirty:false}],active:0};s.assistant ||= {mode:'offline',model:'llama3.2:3b',messages:[]};return s;}
initialState=()=>prepare(oldInitial());prepare(state);save();
function refreshShortcuts(){ $('#desktopIcons').innerHTML=apps.map(a=>appButton(a,'desktop')).join('');$('#startApps').innerHTML=apps.map(a=>appButton(a,'start')).join('');$('#taskApps').innerHTML=apps.filter(a=>['files','directory','terminal','tickets','network','chrome','notepadpp','word','excel','mentor'].includes(a.id)).map(a=>appButton(a,'task')).join('');}refreshShortcuts();
const oldRender=render,oldNetwork=renderNetwork;
const newRenderers={chrome:renderChrome,notepadpp:renderNotepad,office:renderOffice,word:renderWord,excel:renderExcel,powerpoint:renderPowerPoint};
render=()=>{prepare(state);const renderer=newRenderers[currentApp];if(renderer)renderer();else oldRender();const body=$('#appBody');if(body)body.style.zoom=Number(state.preferences.displayScale||100)/100;};
function notify(text){toast(text);}function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function localDialog(title,body,onOK,ok='OK'){const existing=$('#extraDialog');existing?.remove();const root=document.createElement('div');root.id='extraDialog';root.className='dialog-shade';root.innerHTML=`<section class="win-dialog" role="dialog" aria-modal="true" aria-label="${E(title)}"><header class="dialog-title"><span>${E(title)}</span><button data-extra-close aria-label="Close">×</button></header><div class="dialog-content">${body}<div id="extraError" class="dialog-error"></div></div><footer class="dialog-footer"><button class="primary" id="extraOK">${E(ok)}</button><button data-extra-close>Cancel</button></footer></section>`;document.body.append(root);root.querySelectorAll('[data-extra-close]').forEach(b=>b.onclick=()=>root.remove());$('#extraOK').onclick=()=>{if(onOK?.()!==false)root.remove();};root.querySelector('input,textarea,button')?.focus();root.onkeydown=e=>{if(e.key==='Escape')root.remove();if(e.key==='Tab'){const nodes=[...root.querySelectorAll('button,input,textarea,select')];if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus();}}};return root;}

// Clock/calendar stays at the right edge independently of pinned taskbar items.
let calendarMonth=new Date().getMonth(),calendarYear=new Date().getFullYear();
function calendar(){const existing=$('#calendarFlyout');if(existing){existing.remove();return;}const node=document.createElement('section');node.id='calendarFlyout';node.className='calendar-flyout';node.setAttribute('aria-label','Calendar and clock');$('#desktop').append(node);drawCalendar();}
function drawCalendar(){const node=$('#calendarFlyout');if(!node)return;const today=new Date(),first=new Date(calendarYear,calendarMonth,1),days=new Date(calendarYear,calendarMonth+1,0).getDate();node.innerHTML=`<div class="calendar-today">${today.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</div><div class="calendar-heading"><span>${first.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</span><div><button id="calendarPrev" aria-label="Previous month">⌃</button><button id="calendarNext" aria-label="Next month">⌄</button></div></div><div class="calendar-grid">${['Su','Mo','Tu','We','Th','Fr','Sa'].map(d=>`<span>${d}</span>`).join('')}${'<span></span>'.repeat(first.getDay())}${Array.from({length:days},(_,i)=>`<button class="${today.getFullYear()===calendarYear&&today.getMonth()===calendarMonth&&today.getDate()===i+1?'today':''}" data-calendar-day="${i+1}">${i+1}</button>`).join('')}</div><div class="calendar-time">${today.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</div><small class="muted">${E(state.preferences.timezone)}</small>`;$('#calendarPrev').onclick=()=>{calendarMonth--;if(calendarMonth<0){calendarMonth=11;calendarYear--;}drawCalendar();};$('#calendarNext').onclick=()=>{calendarMonth++;if(calendarMonth>11){calendarMonth=0;calendarYear++;}drawCalendar();};node.querySelectorAll('[data-calendar-day]').forEach(b=>b.onclick=()=>{node.querySelectorAll('[data-calendar-day]').forEach(x=>x.classList.toggle('selected',x===b));});}
$('#clockButton').onclick=calendar;
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#calendarFlyout,#clockButton'))$('#calendarFlyout')?.remove();});
const wallpapers={bloom:'radial-gradient(ellipse at 62% 50%,#72a8ff77 0,transparent 45%),linear-gradient(130deg,#071d54,#0859c7 60%,#409aff)',dark:'radial-gradient(ellipse at 65% 55%,#164b82 0,transparent 45%),linear-gradient(125deg,#050b18,#152a45)',sunrise:'radial-gradient(ellipse at 60% 70%,#ffdc9c 0,transparent 45%),linear-gradient(155deg,#546bc3,#d5a2b7 50%,#ffd7a6)',forest:'radial-gradient(ellipse at 50% 90%,#95c7b5 0,transparent 50%),linear-gradient(140deg,#092f31,#1b5e59,#9cbeb4)',purple:'radial-gradient(ellipse at 60% 45%,#a8a0ff 0,transparent 40%),linear-gradient(135deg,#2c1858,#6752b7 60%,#c6bdff)',solid:'#285b9a'};
function wallpaperValue(){const p=state.preferences;if(p.wallpaper==='custom'&&p.wallpaperImage)return `url("${p.wallpaperImage}")`;return wallpapers[p.wallpaper]||wallpapers.bloom;}
function applyPreferences(){const p=state.preferences;$('#desktop').style.background=wallpaperValue();$('#desktop').style.backgroundSize=p.wallpaperFit==='Fit'?'contain':p.wallpaperFit==='Tile'?'auto':p.wallpaperFit==='Stretch'?'100% 100%':'cover';$('#desktop').style.backgroundPosition='center';$('#desktop').style.backgroundRepeat=p.wallpaperFit==='Tile'?'repeat':'no-repeat';$('.wallpaper-art').style.display=['bloom','blue'].includes(p.wallpaper)?'':'none';document.documentElement.style.setProperty('--accent',p.accent);const center=$('.taskbar-center');if(p.taskbarAlignment==='Left'){center.style.left='8px';center.style.transform='none';$('.taskbar-left').style.visibility='hidden';}else{center.style.left='';center.style.transform='';$('.taskbar-left').style.visibility='';}document.body.classList.toggle('settings-dark',p.theme==='Dark');document.documentElement.style.fontSize=14*Number(p.textSize||100)/100+'px';$('#desktop').classList.toggle('night-light',!!p.nightLight);}
applyPreferences();
